create extension if not exists pgcrypto;
create type public.user_role as enum ('student','owner');
create type public.assignment_status as enum ('draft','published','archived');
create type public.suggestion_status as enum ('pending','approved','rejected');
create table public.profiles (user_id uuid primary key references auth.users(id) on delete cascade, display_name text, role public.user_role not null default 'student', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.assignments (id uuid primary key default gen_random_uuid(), title text not null check (char_length(title) between 1 and 160), subject text not null check (char_length(subject) between 1 and 80), description text not null default '', due_at timestamptz, priority text not null default 'Medium' check (priority in ('Low','Medium','High')), status public.assignment_status not null default 'draft', created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.assignment_resources (id uuid primary key default gen_random_uuid(), assignment_id uuid not null references public.assignments(id) on delete cascade, title text not null, url text not null check (url ~* '^https?://'), description text, sort_order int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.assignment_progress (id uuid primary key default gen_random_uuid(), assignment_id uuid not null references public.assignments(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, is_completed boolean not null default false, completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (assignment_id,user_id));
create table public.personal_tasks (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null check (char_length(title) between 1 and 160), description text not null default '', subject text not null default 'Personal', due_at timestamptz, priority text not null default 'Medium' check (priority in ('Low','Medium','High')), is_completed boolean not null default false, completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.assignment_suggestions (id uuid primary key default gen_random_uuid(), submitted_by uuid not null references auth.users(id) on delete cascade, title text not null check (char_length(title) between 1 and 160), subject text not null, description text not null default '', proposed_due_at timestamptz, status public.suggestion_status not null default 'pending', reviewer_notes text, reviewed_by uuid references auth.users(id), reviewed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index assignments_status_due_idx on public.assignments(status,due_at); create index progress_user_idx on public.assignment_progress(user_id); create index tasks_user_idx on public.personal_tasks(user_id); create index suggestions_submitter_idx on public.assignment_suggestions(submitted_by);
alter table public.profiles enable row level security; alter table public.assignments enable row level security; alter table public.assignment_resources enable row level security; alter table public.assignment_progress enable row level security; alter table public.personal_tasks enable row level security; alter table public.assignment_suggestions enable row level security;
create or replace function public.is_owner() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where user_id=auth.uid() and role='owner') $$;
create policy "published assignments are public" on public.assignments for select using (status='published' or public.is_owner()); create policy "owner manages assignments" on public.assignments for all using (public.is_owner()) with check (public.is_owner());
create policy "published resources are public" on public.assignment_resources for select using (exists(select 1 from assignments a where a.id=assignment_id and (a.status='published' or public.is_owner()))); create policy "owner manages resources" on public.assignment_resources for all using (public.is_owner()) with check (public.is_owner());
create policy "users read own progress" on public.assignment_progress for select using (user_id=auth.uid()); create policy "users write own progress" on public.assignment_progress for insert with check (user_id=auth.uid()); create policy "users update own progress" on public.assignment_progress for update using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "users manage own tasks" on public.personal_tasks for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "users read own suggestions" on public.assignment_suggestions for select using (submitted_by=auth.uid() or public.is_owner()); create policy "students submit suggestions" on public.assignment_suggestions for insert with check (submitted_by=auth.uid() and status='pending'); create policy "owner reviews suggestions" on public.assignment_suggestions for update using (public.is_owner()) with check (public.is_owner());
create policy "users read own profile" on public.profiles for select using (user_id=auth.uid() or public.is_owner());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(user_id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name',split_part(new.email,'@',1))); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
-- Owner provisioning: after creating the account, run: update public.profiles set role='owner' where user_id='AUTH_USER_UUID';
